# ============================================================
# AEGIS NIDS - STEP 3: Event Fabric Runtime
# ============================================================
# Centralizes queue runtime into a single event_fabric.zig module:
#   - Backpressure signaling (low/medium/high/saturated)
#   - Per-event latency tracking (enqueue -> pop, via ring of 256 entries)
#   - Depth thresholds (medium=50%, high=80% configurable)
#   - Drop policy selection (block_new / drop_oldest / drop_lowest_priority)
#   - Unified FabricMetrics snapshot (single struct for ops/CLI)
#   - nose_contract.zig refactored as thin facade (legacy API preserved)
# ============================================================
$ErrorActionPreference = 'Continue'
$DeployRoot = $PSScriptRoot
if (-not $DeployRoot) { $DeployRoot = (Get-Location).Path }
Write-Host "[DEPLOY] AEGIS STEP 3 - Event Fabric Runtime"
Write-Host "[DEPLOY] Deploy root: $DeployRoot"
Write-Host ""

function Deploy-File {
    param([string]$RelativePath, [int]$ExpectedLines, [string]$Base64Content)
    $FullPath = Join-Path $DeployRoot $RelativePath
    $Dir = Split-Path -Parent $FullPath
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
        Write-Host "  [MKDIR] Created: $Dir"
    }
    $BackupPath = "$FullPath.step3_backup"
    if (Test-Path $FullPath) {
        Copy-Item -Path $FullPath -Destination $BackupPath -Force
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Content)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    $ActualLines = (Get-Content $FullPath).Count
    if ($ActualLines -ne $ExpectedLines) {
        Write-Host "  [WARN] $RelativePath : actual=$ActualLines expected=$ExpectedLines"
    } else {
        Write-Host "  [OK] $RelativePath : $ActualLines lines"
    }
}

# File 1: core/event_fabric.zig (event_fabric.zig, 712 lines)
$B64_1 = ''
Deploy-File -RelativePath "core/event_fabric.zig" -ExpectedLines 712 -Base64Content $B64_1
Write-Host ""

# File 2: core/nose_contract.zig (nose_contract.zig, 317 lines)
$B64_2 = ''
Deploy-File -RelativePath "core/nose_contract.zig" -ExpectedLines 317 -Base64Content $B64_2
Write-Host ""

# File 3: build.zig (build.zig, 76 lines)
$B64_3 = ''
Deploy-File -RelativePath "build.zig" -ExpectedLines 76 -Base64Content $B64_3
Write-Host ""

# ============================================================
# Build and test
# ============================================================
Write-Host "[BUILD] Running zig build..."
& zig build 2>&1 | Out-Host
$buildExit = $LASTEXITCODE
if ($buildExit -ne 0) {
    Write-Host "[BUILD] FAILED (exit $buildExit)"
    exit 1
}
Write-Host "[BUILD] SUCCESS"
Write-Host ""

Write-Host "[TEST] Running zig build test (uses ErrorActionPreference=Continue)..."
& zig build test 2>&1 | Out-Host
$testExit = $LASTEXITCODE
if ($testExit -eq 0) {
    Write-Host "[TEST] ALL ZIG TESTS PASSED"
} else {
    Write-Host "[TEST] FAILED (exit $testExit)"
    exit $testExit
}
Write-Host ""

Write-Host "============================================================"
Write-Host "STEP 3 COMPLETE: Event Fabric Runtime"
Write-Host "============================================================"
Write-Host ""
Write-Host "Files deployed:"
Write-Host "  core/event_fabric.zig    (NEW)"
Write-Host "    - Pressure enum: low/medium/high/saturated"
Write-Host "    - DropPolicy enum: block_new/drop_oldest/drop_lowest_priority"
Write-Host "    - FabricConfig: capacity_per_priority + thresholds + drop_policy"
Write-Host "    - FabricMetrics: unified snapshot (pending + pressure + latency + counts)"
Write-Host "    - submitWithBackpressure(): returns { accepted, pressure }"
Write-Host "    - currentPressure(): query without submit"
Write-Host "    - popEvent(): tracks enqueue->pop latency via 256-entry ring"
Write-Host "    - 11 STEP3 tests covering pressure thresholds + latency + metrics"
Write-Host ""
Write-Host "  core/nose_contract.zig   (REPLACE, refactor to facade)"
Write-Host "    - All legacy API preserved (submitEvent/popEvent/getStats)"
Write-Host "    - submitEvent returns legacy SubmitResult enum"
Write-Host "    - New: currentPressure(), submitWithBackpressure(), getMetrics()"
Write-Host "    - 11 backward-compat tests (all existing tests still pass)"
Write-Host ""
Write-Host "  build.zig                (REPLACE, add event_fabric.zig to test_files)"
Write-Host ""
Write-Host "New test count: ~10 (event_fabric.zig) + ~11 (nose_contract.zig) = ~21 new tests"
Write-Host "Total Zig tests now: ~245 (was ~221 after STEP 2B)"
Write-Host ""
Write-Host "Suggested git commands:"
Write-Host "  git add -A"
Write-Host "  git commit -m `"feat: step 3 - event fabric runtime (backpressure + metrics + latency)`""
Write-Host "  git push"
